30	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
31	enum Indent {
32	    Spaces(u8),
33	    Tabs,
34	    DefaultTwoSpaces,
35	}
36	
37	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
38	enum LineEnding {
39	    Lf,
40	    CrLf,
41	}
