43	impl PackageJson {
44	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
45	        let rel_path = decl.path.clone();
46	        let abs_path = ctx.workspace_root.join(&rel_path);
47	
48	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
49	            path: rel_path.clone(),
50	            message: e.to_string(),
51	        })?;
52	
53	        let has_bom = content.starts_with('\u{FEFF}');
54	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
55	        let mut fingerprint = detect_fingerprint(clean_content);
56	        fingerprint.has_bom = has_bom;
57	
58	        let doc: Map<String, Value> =
59	            serde_json::from_str(clean_content).map_err(|e| ManifestError::Parse {
60	                path: rel_path.clone(),
61	                format: ManifestFormat::PackageJson,
62	                message: e.to_string(),
63	            })?;
64	
65	        Ok(PackageJson {
66	            path: rel_path,
67	            absolute: abs_path,
68	            role: decl.role.clone(),
69	            doc,
70	            fingerprint,
71	            npm_workspace_kind: ctx.npm_workspace_kind,
72	        })
73	    }
74	
75	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
76	        let indent_str = match self.fingerprint.indent {
77	            Indent::Spaces(n) => " ".repeat(n as usize),
78	            Indent::Tabs => "\t".to_string(),
79	            Indent::DefaultTwoSpaces => "  ".to_string(),
80	        };
81	
82	        let mut map = IndexMap::new();
83	        for (k, v) in &self.doc {
84	            map.insert(k, v);
85	        }
86	
87	        let mut out = format_json_pretty(&map, &indent_str)?;
88	        if self.fingerprint.line_ending == LineEnding::CrLf {
89	            out = out.replace("\r\n", "\n").replace('\n', "\r\n");
90	        }
91	
92	        if !self.fingerprint.trailing_newline && out.ends_with('\n') {
93	            if out.ends_with("\r\n") {
94	                out.truncate(out.len() - 2);
95	            } else {
96	                out.truncate(out.len() - 1);
97	            }
98	        }
99	
100	        if self.fingerprint.has_bom {
101	            out = format!("\u{FEFF}{}", out);
102	        }
103	
104	        crate::atomic::atomic_write(&self.absolute, &out, permit).map_err(|e| {
105	            ManifestError::Write {
106	                path: self.path.clone(),
107	                message: e.to_string(),
108	            }
109	        })
110	    }
111	}
112	
113	fn detect_fingerprint(content: &str) -> FormatFingerprint {
114	    let line_ending = if content.contains("\r\n") {
115	        LineEnding::CrLf
116	    } else {
117	        LineEnding::Lf
118	    };
119	
120	    let trailing_newline = content.ends_with('\n');
121	
122	    let mut indent = Indent::DefaultTwoSpaces;
123	    for line in content.lines() {
124	        let trimmed_start = line.trim_start();
125	        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
126	            let leading = &line[..line.len() - trimmed_start.len()];
127	            if leading.contains('\t') {
128	                indent = Indent::Tabs;
129	            } else {
130	                indent = Indent::Spaces(leading.len() as u8);
131	            }
132	            break;
133	        }
134	    }
135	
136	    let has_bom = content.starts_with('\u{FEFF}');
137	    FormatFingerprint {
138	        indent,
139	        trailing_newline,
140	        line_ending,
141	        has_bom,
142	    }
143	}
