366	fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
367	    if let Some(rest) = s.strip_prefix("workspace:") {
368	        if let Some(kind) = ws_kind {
369	            return DepSpec::Workspace(kind);
370	        }
371	        return DepSpec::Opaque(format!("workspace:{rest}"));
372	    }
373	    if let Some(rest) = s.strip_prefix("catalog:") {
374	        let name = if rest.is_empty() {
375	            None
376	        } else {
377	            Some(rest.to_string())
378	        };
379	        return DepSpec::Catalog(name);
380	    }
381	
382	    if crate::common::is_bare_semver(s) {
383	        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
384	            return DepSpec::Exact(v);
385	        }
386	    }
387	
388	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
389	        return DepSpec::Range(req, s.to_string());
390	    }
391	
392	    DepSpec::Opaque(s.to_string())
393	}
