428	pub fn detect_npm_workspace_kind(
429	    workspace_root: &Path,
430	) -> Result<Option<WorkspaceKind>, ManifestError> {
431	    if workspace_root.join("pnpm-lock.yaml").exists() {
432	        return Ok(Some(WorkspaceKind::Pnpm));
433	    }
434	    if workspace_root.join("yarn.lock").exists() {
435	        return Ok(Some(WorkspaceKind::Yarn));
436	    }
437	    if workspace_root.join("package-lock.json").exists() {
438	        return Ok(Some(WorkspaceKind::Npm));
439	    }
440	
441	    let root_pkg_json = workspace_root.join("package.json");
442	    if root_pkg_json.exists() {
443	        if let Ok(content) = fs::read_to_string(&root_pkg_json) {
444	            if let Ok(val) = serde_json::from_str::<Value>(&content) {
445	                if val.get("workspaces").is_some() {
446	                    return Ok(Some(WorkspaceKind::Npm));
447	                }
448	            }
449	        }
450	    }
451	
452	    Ok(None)
453	}
