14	/// Fetches the full, unfiltered list of every tag name in the repository at
15	/// `root`, via [`GitAccess`] (native gix, falling back to a `CommandRunner`-
16	/// shelled `git tag --list` when gix is unavailable -- most notably on
17	/// `wasm32`).
18	///
19	/// Deliberately fetches with no glob pattern (the full tag list): callers
20	/// apply their own glob filtering afterwards via [`matching_tags`], using
21	/// the exact same `globset` matcher both `GitDataSource` backends use
22	/// internally. This guarantees identical tag-selection semantics
23	/// regardless of which backend sourced the raw list, and lets the fetch be
24	/// batched once across every package (see [`TagIndex::build`]) instead of
25	/// once per package -- important on `wasm32`, where each `CommandRunner`
26	/// call is a full Extism guest<->host round-trip.
27	fn fetch_all_tags<R: CommandRunner>(runner: &R, root: &Path) -> Result<Vec<String>, GraphError> {
28	    let git = GitAccess::discover(root, runner);
29	    let tags = git.list_tags(None)?;
30	    Ok(tags.into_iter().map(|t| t.0).collect())
31	}
